import signal, subprocess, time, urllib.request
p=subprocess.Popen(['./server','--db','<TEMP_PATH>','--listen','127.0.0.1:18122'],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
try:
  deadline=time.monotonic()+10
  while time.monotonic()<deadline:
    if p.poll() is not None: raise AssertionError(p.stderr.read().decode())
    try:
      assert urllib.request.urlopen('http://127.0.0.1:18122/health',timeout=.3).status==200
      break
    except Exception: time.sleep(.05)
  else: raise AssertionError('health did not become ready')
  p.send_signal(signal.SIGTERM)
  assert p.wait(timeout=12)==0
finally:
  if p.poll() is None: p.kill(); p.wait()
print('SIGTERM shutdown check passed: server reached healthy state and exited cleanly')
